// explorer.ts — the design system's component explorer, Storybook-style. GENERATED by the
// blinkpages-migrate skill (templates/design-system/): nobody edits it. The curated part is
// stories.ts beside it, written by the style-library agent (oneshot/briefs/style-library.md §4).
//
// Every story in stories.ts becomes a page of its own under /design-system/story/<id>/ (the route
// src/pages/design-system/story/[id].astro), rendered alone in the site's CSS. The explorer on
// /design-system/#explorer frames one at a time at a chosen device width and background, with its
// controls, props table, code and the pages that use it.
//   - A component story: the component's Props (its `interface Props` or `type Props = …`, with each
//     member's comment and the defaults in `const { … } = Astro.props` or `props.x ?? "…"`) become the
//     props table, and each enum or boolean prop a control. An enum may be a named union, declared in
//     the component or in a .ts file it imports from by a relative path; an optional one can also be
//     left unset. A static site can't re-render a component in the browser, so every combination of
//     those controls is pre-rendered as its own page (up to 24; past that, one control at a time from
//     the story's own values). A list or object prop is shown, not edited.
//   - An HTML story (a class-based atom: a button is markup plus global classes): its {{arg}}
//     placeholders are live controls, and the explorer posts the new markup into the frame.
import fs from "node:fs";
import path from "node:path";
import { slStories, type Control, type Layout, type StoryEntry } from "./stories";

export type PropDoc = {
  name: string; type: string; optional: boolean; default?: string; description?: string; options?: string[]; control: "select" | "boolean" | "text" | "number" | "none";
  resolved?: string; // a named union's values ("navy" | "maroon"), for the props table
  unset?: boolean; // an optional enum that may stay unset: null in a combo, the prop left out
};
/* a combination's values; null is an enum left unset (the prop is left out of the page) */
export type Combo = { id: string; values: Record<string, string | boolean | null> };
export type ExplorerStory = { slug: string; name: string; note?: string; background?: string; layout: Layout; args: Record<string, unknown>; slot?: string; wrap: Wrap[]; combos: Combo[] };
export type ExplorerEntry = {
  slug: string; title: string; group: string; description?: string; kind: "component" | "html"; component?: string;
  props: PropDoc[]; controls: Record<string, Control>; html?: string; usedOn: { label: string; href?: string }[]; stories: ExplorerStory[];
};
/* a story's wrapper, outermost first (stories.ts `wrap`; read loosely, so an older stories.ts without the type still builds) */
export type Wrap = { class?: string; style?: string; tag?: string };
export type StoryPage = { id: string; title: string; component?: string; html?: string; args: Record<string, unknown>; slot?: string; background?: string; layout: Layout; wrap: Wrap[] };
const wrapOf = (...from: unknown[]): Wrap[] => {
  const w = (from.find((x) => (x as { wrap?: unknown })?.wrap !== undefined) as { wrap?: Wrap | Wrap[] } | undefined)?.wrap;
  return (Array.isArray(w) ? w : w ? [w] : []).filter((x) => x && typeof x === "object");
};

const ROOT = process.cwd();
const COMBO_CAP = 24;
const slug = (s: string) => s.toLowerCase().replace(/\.astro$/, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "story";
const frontmatterOf = (src: string) => src.match(/^---\r?\n([\s\S]*?)\r?\n---/)?.[1] ?? "";
const unquote = (v?: string) => (v && /^(["'`]).*\1$/.test(v) ? v.slice(1, -1) : v);

/* split on a separator (a comma by default) outside quotes, brackets, braces and generics */
function splitTop(s: string, sep = ",") {
  const out: string[] = [];
  let depth = 0, quote = "", cur = "";
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quote) { if (ch === quote) quote = ""; }
    else if (ch === '"' || ch === "'" || ch === "`") quote = ch;
    else if ("([{<".includes(ch)) depth++;
    else if (")]}>".includes(ch) && !(ch === ">" && s[i - 1] === "=")) depth--;
    else if (ch === sep && depth === 0) { out.push(cur); cur = ""; continue; }
    cur += ch;
  }
  if (cur.trim()) out.push(cur);
  return out;
}

/* ---- the type declarations a component can see: its frontmatter, then the .ts files it imports names
   from by a relative path, one hop (cascade-partners keeps each family's props in parts/types.ts, and
   `import type { ArchiveEntry as Entry }` renames one). `type Props = MemberProps` and a member typed by
   a named union (`variant?: CTABandVariant`, one fleet site) read through them (2026-11-03). ---- */
type Decl = { kind: "type"; body: string } | { kind: "interface"; ext: string[]; body: string };
type Scope = { decl: (name: string) => Decl | undefined };
type Member = { name: string; optional: boolean; type: string; doc?: string };

/* where a type that starts at i ends: a ; or , at depth 0, a comment at depth 0, the close of the body
   it sits in, or a line break at depth 0 once the type is whole (a next line may go on with | or &) */
function typeEnd(s: string, i: number) {
  let depth = 0, quote = "";
  const start = i;
  for (; i < s.length; i++) {
    const ch = s[i];
    if (quote) { if (ch === "\\") i++; else if (ch === quote) quote = ""; continue; }
    if (ch === '"' || ch === "'" || ch === "`") { quote = ch; continue; }
    if (s.startsWith("//", i) || s.startsWith("/*", i)) {
      if (depth === 0) return i;
      const e = s.startsWith("//", i) ? s.indexOf("\n", i) - 1 : s.indexOf("*/", i + 2) + 1;
      i = e < 0 ? s.length : e;
      continue;
    }
    if ("([{<".includes(ch)) depth++;
    else if (ch === ">" && s[i - 1] === "=") continue;
    else if (")]}>".includes(ch)) { if (depth === 0) return i; depth--; }
    else if (depth === 0 && (ch === ";" || ch === ",")) return i;
    else if (depth === 0 && ch === "\n") {
      const sofar = s.slice(start, i).trim(), next = s.slice(i + 1).trimStart();
      if (sofar && !/[|&:=,(<]$/.test(sofar) && !/^[|&]/.test(next)) return i;
    }
  }
  return i;
}
/* a balanced { … }'s inner text, from its opening brace */
function braced(s: string, open: number) {
  let depth = 0, quote = "";
  for (let i = open; i < s.length; i++) {
    const ch = s[i];
    if (quote) { if (ch === "\\") i++; else if (ch === quote) quote = ""; continue; }
    if (ch === '"' || ch === "'" || ch === "`") quote = ch;
    else if (ch === "{") depth++;
    else if (ch === "}" && --depth === 0) return s.slice(open + 1, i);
  }
  return s.slice(open + 1);
}
const cleanType = (t: string) => t.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\/\/[^\n]*/g, "").replace(/\s+/g, " ").trim().replace(/^\|\s*/, "");

function scopeOf(file: string, fm: string): Scope {
  const renames = new Map<string, string>();
  let src = fm;
  for (const m of fm.matchAll(/import\s+(?:type\s+)?\{([^}]*)\}\s*from\s*["'](\.{1,2}\/[^"']+)["']/g)) {
    const base = path.resolve(path.dirname(file), m[2]);
    const f = [base, `${base}.ts`, `${base}.d.ts`, path.join(base, "index.ts")].find((p) => /\.ts$/.test(p) && fs.existsSync(p));
    if (!f) continue;
    src += "\n" + fs.readFileSync(f, "utf8");
    for (const spec of m[1].split(",")) {
      const [name, local] = spec.trim().replace(/^type\s+/, "").split(/\s+as\s+/);
      if (name && local) renames.set(local.trim(), name.trim());
    }
  }
  const found = new Map<string, Decl | undefined>();
  const decl = (name: string): Decl | undefined => {
    if (found.has(name)) return found.get(name);
    found.set(name, undefined); // a name that leads back to itself ends here
    let d: Decl | undefined;
    const m = new RegExp(`(?:^|[\\s;])(?:export\\s+)?(?:declare\\s+)?(type|interface)\\s+${name.replace(/\$/g, "\\$")}\\b(?:<[^>]*>)?\\s*(=|extends\\b|\\{)`, "m").exec(src);
    if (m?.[1] === "type" && m[2] === "=") {
      const at = m.index + m[0].length;
      d = { kind: "type", body: cleanType(src.slice(at, typeEnd(src, at))) };
    } else if (m?.[1] === "interface") {
      const open = src.indexOf("{", m.index + m[0].length - 1);
      const ext = m[2] === "extends" ? splitTop(src.slice(m.index + m[0].length, open)).map((x) => x.trim()).filter(Boolean) : [];
      d = open < 0 ? undefined : { kind: "interface", ext, body: braced(src, open) };
    }
    found.set(name, d ?? (renames.has(name) ? decl(renames.get(name)!) : undefined));
    return found.get(name);
  };
  return { decl };
}

/* the members of an object type's body, each with its comment (a comment above it, or after it on its line) */
function membersOf(body: string): Member[] {
  const out: Member[] = [];
  let i = 0, doc = "";
  const add = (c: string) => { c = c.trim(); if (c) doc = doc ? `${doc} ${c}` : c; };
  while (i < body.length) {
    const rest = body.slice(i);
    const ws = rest.match(/^[\s;,]+/);
    if (ws) { i += ws[0].length; continue; }
    if (rest.startsWith("/*")) {
      const e = rest.indexOf("*/");
      add(rest.slice(2, e < 0 ? undefined : e).split("\n").map((l) => l.replace(/^\s*\*+\s?/, "").trim()).filter(Boolean).join(" "));
      i += e < 0 ? rest.length : e + 2;
      continue;
    }
    if (rest.startsWith("//")) { const e = rest.indexOf("\n"); add(rest.slice(2, e < 0 ? undefined : e)); i += e < 0 ? rest.length : e; continue; }
    const m = rest.match(/^(?:readonly\s+)?([A-Za-z_$][\w$]*|"[^"]*"|'[^']*')(\?)?\s*:\s*/);
    const at = i + (m ? m[0].length : 0), end = typeEnd(body, at);
    if (m) {
      const tail = body.slice(end).match(/^[ \t]*[;,]?[ \t]*\/\/[ \t]*([^\n]*)/);
      out.push({ name: m[1].replace(/^["']|["']$/g, ""), optional: !!m[2], type: cleanType(body.slice(at, end)), doc: tail?.[1].trim() || doc || undefined });
      i = tail ? end + tail[0].length : end;
    } else i = Math.max(end, i + 1); // an index signature or a method: no prop of its own
    doc = "";
  }
  return out;
}

/* the members of a type: an object literal, a named interface (with what it extends) or alias, an
   intersection of them, or Partial<…> / Readonly<…> of one */
function membersOfType(t: string, scope: Scope, seen = new Set<string>()): Member[] {
  t = t.trim();
  if (t.startsWith("{")) return membersOf(braced(t, 0));
  const parts = splitTop(t, "&");
  if (parts.length > 1) return parts.flatMap((p) => membersOfType(p, scope, seen));
  const wrap = t.match(/^(Partial|Readonly)<([\s\S]+)>$/);
  if (wrap) return membersOfType(wrap[2], scope, seen).map((m) => (wrap[1] === "Partial" ? { ...m, optional: true } : m));
  if (!/^[A-Za-z_$][\w$]*$/.test(t) || seen.has(t)) return [];
  seen.add(t);
  const d = scope.decl(t);
  if (!d) return [];
  return d.kind === "type" ? membersOfType(d.body, scope, seen) : [...d.ext.flatMap((e) => membersOfType(e, scope, seen)), ...membersOf(d.body)];
}

/* the string literals a type allows, through named unions ("navy" | "maroon", or CTABandVariant naming
   them). null and undefined only make the prop nullable; any other member means no list of options */
function literalsOf(t: string, scope: Scope, seen = new Set<string>()): { values: string[]; nullable: boolean } | undefined {
  const values: string[] = [];
  let nullable = false;
  for (const raw of splitTop(t, "|")) {
    const p = raw.trim().replace(/^\(([\s\S]*)\)$/, "$1").trim();
    if (!p) continue;
    if (/^(null|undefined)$/.test(p)) { nullable = true; continue; }
    const q = p.match(/^(["'])(.*)\1$/);
    if (q) { values.push(q[2]); continue; }
    const d = /^[A-Za-z_$][\w$]*$/.test(p) && !seen.has(p) ? (seen.add(p), scope.decl(p)) : undefined;
    const sub = d?.kind === "type" ? literalsOf(d.body, scope, seen) : undefined;
    if (!sub) return undefined;
    values.push(...sub.values);
    nullable ||= sub.nullable;
  }
  return values.length ? { values: [...new Set(values)], nullable } : undefined;
}

/** The props of an .astro component: name, type, whether optional, default, the member's comment,
 *  and the control the explorer gives it. Props is `interface Props` (with what it extends) or
 *  `type Props = …`: an object type, a named type, or an intersection of them. */
export function propsOf(file: string): PropDoc[] {
  if (!fs.existsSync(file)) return [];
  const fm = frontmatterOf(fs.readFileSync(file, "utf8"));
  const scope = scopeOf(file, fm);
  /* the defaults: `const { a = "x" } = Astro.props`, and `props.a ?? "x"` on Astro.props or a const that holds it */
  const defaults = new Map<string, string>();
  const d = fm.match(/const\s*\{([\s\S]*?)\}\s*(?::\s*[\w<>[\], ]+)?=\s*Astro\.props/);
  if (d) for (const part of splitTop(d[1])) {
    const m = part.trim().match(/^(?:\.\.\.)?([A-Za-z_$][\w$]*)(?:\s*:\s*[A-Za-z_$][\w$]*)?(?:\s*=\s*([\s\S]+))?$/);
    if (m?.[2]) defaults.set(m[1], m[2].trim());
  }
  const holders = ["Astro\\.props", ...[...fm.matchAll(/(?:const|let)\s+([A-Za-z_$][\w$]*)\s*(?::\s*[\w<>[\]]+)?\s*=\s*Astro\.props\b\s*;?\s*$/gm)].map((m) => m[1].replace(/\$/g, "\\$"))];
  for (const h of holders) for (const m of fm.matchAll(new RegExp(`\\b${h}\\.([A-Za-z_$][\\w$]*)\\s*\\?\\?\\s*("[^"]*"|'[^']*'|true|false|-?\\d+(?:\\.\\d+)?)`, "g"))) if (!defaults.has(m[1])) defaults.set(m[1], m[2]);
  /* one row a name: a member the interface declares again over what it extends takes its place */
  const members = new Map<string, Member>();
  for (const m of membersOfType("Props", scope)) members.set(m.name, m);
  return [...members.values()].map((m) => {
    const bare = splitTop(m.type, "|").map((x) => x.trim()).filter((x) => x && !/^(null|undefined)$/.test(x)).join(" | ");
    const lit = literalsOf(m.type, scope);
    const options = lit?.values, dflt = unquote(defaults.get(m.name));
    const control = options ? "select" : bare === "boolean" ? "boolean" : bare === "number" ? "number" : bare === "string" ? "text" : "none";
    return {
      name: m.name, type: m.type, optional: m.optional, default: defaults.get(m.name), description: m.doc, options, control,
      /* a named union's values, for the props table */
      resolved: options && !/^["']/.test(bare) ? options.map((o) => JSON.stringify(o)).join(" | ") : undefined,
      /* an optional or nullable enum whose default is none of its options can stay unset, as a page
         that leaves it out has it: the explorer offers "(not set)" beside the options */
      unset: (!!options && (m.optional || !!lit?.nullable) && !options.includes(dflt ?? "\u0000")) || undefined,
    } satisfies PropDoc;
  });
}

/* a control's starting value: the story's arg, else the prop's default, else unset (null) when it may
   be, else its first option / off */
function startOf(p: PropDoc, args: Record<string, unknown>): string | boolean | null {
  if (p.name in args) return args[p.name] as string | boolean;
  if (p.control === "boolean") return p.default === "true";
  const d = unquote(p.default);
  if (d !== undefined && (!p.options || p.options.includes(d))) return d;
  return p.unset ? null : p.options?.[0] ?? "";
}

/* the pre-rendered combinations of a component story's enum and boolean props */
function combosOf(id: string, props: PropDoc[], args: Record<string, unknown>): Combo[] {
  type Values = Combo["values"];
  const axes = props.filter((p) => p.control === "select" || p.control === "boolean").map((p) => ({ name: p.name, values: (p.control === "boolean" ? [false, true] : [...(p.unset ? [null] : []), ...p.options!]) as (string | boolean | null)[] }));
  const base: Values = Object.fromEntries(props.filter((p) => axes.some((a) => a.name === p.name)).map((p) => [p.name, startOf(p, args)]));
  const total = axes.reduce((n, a) => n * a.values.length, 1);
  let list: Values[];
  if (total <= COMBO_CAP) {
    list = axes.reduce<Values[]>((acc, a) => acc.flatMap((c) => a.values.map((v) => ({ ...c, [a.name]: v }))), [{}]);
    /* the story's own values first */
    list.sort((x, y) => Number(JSON.stringify(y) === JSON.stringify(base)) - Number(JSON.stringify(x) === JSON.stringify(base)));
  } else {
    list = [base, ...axes.flatMap((a) => a.values.filter((v) => v !== base[a.name]).map((v) => ({ ...base, [a.name]: v })))];
  }
  return list.map((values, i) => ({ id: `${id}--${i}`, values }));
}

/* a page's URL from its file under src/pages ([param] routes keep the file name) */
function routeOf(rel: string) {
  const r = rel.replace(/\\/g, "/").replace(/\.(astro|mdx?)$/, "").replace(/(^|\/)index$/, "");
  return /\[/.test(r) ? undefined : `/${r}${r ? "/" : ""}`;
}

/* the pages, layouts and components that import a component */
function usedOnOf(component: string) {
  const target = path.join(ROOT, "src", "components", component);
  const out: { label: string; href?: string }[] = [];
  const walk = (dir: string, kind: "pages" | "layouts" | "components") => {
    if (!fs.existsSync(dir)) return;
    for (const f of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, f.name);
      /* the design-system page's own files (design-system, or a legacy style-library) never count */
      if (f.isDirectory()) { if (!(kind === "components" && /^(design-system|style-library)$/.test(f.name))) walk(full, kind); continue; }
      if (!/\.(astro|mdx?)$/.test(f.name) || full === target) continue;
      const rel = path.relative(path.join(ROOT, "src", kind), full);
      if (kind === "pages" && /^(design-system|style-library)/.test(rel)) continue;
      const src = fs.readFileSync(full, "utf8");
      for (const m of src.matchAll(/from\s+["']([^"']+\.astro)["']/g)) {
        const spec = m[1].startsWith("@/") ? path.join(ROOT, "src", m[1].slice(2)) : path.resolve(path.dirname(full), m[1]);
        if (spec !== target) continue;
        const href = kind === "pages" ? routeOf(rel) : undefined;
        out.push({ label: kind === "pages" ? href ?? `src/pages/${rel}` : `${kind === "layouts" ? "layout" : "component"} ${rel}`, href });
        break;
      }
    }
  };
  walk(path.join(ROOT, "src", "pages"), "pages");
  walk(path.join(ROOT, "src", "layouts"), "layouts");
  walk(path.join(ROOT, "src", "components"), "components");
  return out;
}

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]!);
/** An HTML story's markup for a set of args: a text control is escaped, a select or boolean inserts
 *  its (class) value as written. The explorer runs the same substitution in the browser. */
export function renderHtml(html: string, controls: Record<string, Control>, args: Record<string, unknown>) {
  return html.replace(/\{\{\s*([\w-]+)\s*\}\}/g, (_, k: string) => {
    const c = controls[k], v = args[k];
    if (c?.type === "boolean") return v ? c.on : c.off ?? "";
    return c?.type === "text" || !c ? esc(String(v ?? "")) : String(v ?? "");
  });
}

let cache: ExplorerEntry[] | undefined;
/** Every entry of stories.ts, expanded: props, controls, stories and their pre-rendered pages. */
export function explorer(): ExplorerEntry[] {
  if (cache) return cache;
  const seen = new Set<string>();
  cache = slStories.map((e: StoryEntry) => {
    const title = e.title ?? path.basename(e.component ?? "Story", ".astro");
    let s = slug(title);
    while (seen.has(s)) s += "-2";
    seen.add(s);
    const props = e.component ? propsOf(path.join(ROOT, "src", "components", e.component)) : [];
    const stories = (e.stories?.length ? e.stories : [{ name: "Default" }]).map((st) => {
      const args = { ...(e.args ?? {}), ...(st.args ?? {}) };
      const id = `${s}--${slug(st.name)}`;
      return {
        slug: slug(st.name), name: st.name, note: st.note, background: st.background, layout: st.layout ?? e.layout ?? (e.html ? "centered" : "padded"),
        args, slot: st.slot ?? e.slot, wrap: wrapOf(st, e), combos: e.component ? combosOf(id, props, args) : [{ id: `${id}--0`, values: {} }],
      } satisfies ExplorerStory;
    });
    return { slug: s, title, group: e.group, description: e.description, kind: e.component ? "component" : "html", component: e.component, props, controls: e.controls ?? {}, html: e.html, usedOn: e.component ? usedOnOf(e.component) : [], stories } satisfies ExplorerEntry;
  });
  return cache;
}

/** One page per pre-rendered combination, for the story route's getStaticPaths. */
export function storyPages(): StoryPage[] {
  return explorer().flatMap((e) => e.stories.flatMap((st) => st.combos.map((c) => {
    const args: Record<string, unknown> = { ...st.args, ...c.values };
    /* an enum left unset is left out, so the component falls back to its own default */
    for (const [k, v] of Object.entries(c.values)) if (v === null) delete args[k];
    return { id: c.id, title: `${e.title} · ${st.name}`, component: e.component, html: e.html !== undefined ? renderHtml(e.html, e.controls, args) : undefined, args, slot: st.slot, background: st.background, layout: st.layout, wrap: st.wrap };
  })));
}

/** The site's font stylesheets as its layouts link them (Google Fonts, the self-hosted sheet, or an
 *  Elementor port's local google-fonts sheet); a URL in a data-* attribute is not one. */
export function fontSheets() {
  const dir = path.join(ROOT, "src", "layouts");
  const out = new Set<string>();
  if (fs.existsSync(dir)) for (const f of fs.readdirSync(dir)) {
    if (!f.endsWith(".astro")) continue;
    const src = fs.readFileSync(path.join(dir, f), "utf8");
    for (const m of src.matchAll(/(data-[\w-]+=\s*\{?\s*)?["'`](https:\/\/fonts\.googleapis\.com\/css2?\?[^"'`\s]+|\/assets\/(?:fonts\/|[^"'`\s]*google-fonts\/)[^"'`\s?]+\.css(?:\?[^"'`\s]*)?|https:\/\/use\.typekit\.net\/[\w-]+\.css)["'`]/g)) if (!m[1] && !/&&\s*(\(\s*)?<link\b[^>]*$/.test(src.slice(Math.max(0, (m.index ?? 0) - 200), m.index))) out.add(m[2].replace(/&amp;/g, "&"));
  }
  return [...out];
}
